t.guides["forever/horde/40-50/01-stranglethorn-vale"] = (function() return {
		["Draenethyst crystals"] = "드레니시스트 수정",
		["Fly to {object:3202}"] = "{object:3202}(으)로 날아가기",
		["Follow the coast south. The naga explorers wade along the shore and carry the reed bundles; the {object:759} bubbles in the hills just east of them."] = "해안을 따라 남쪽으로 가세요. 나가 탐험가가 물가를 걸어 다니며 갈대 묶음을 지니고 있습니다. {object:759}은(는) 그 바로 동쪽 언덕에서 솟아납니다.",
		["Hand Unbagwa the fangs and stay by him: he calls three waves of gorillas, then {npc:1514}. Fight them one at a time."] = "운바그와에게 송곳니를 건네고 곁에 있으세요. 그가 고릴라 세 무리를 부른 뒤 {npc:1514}을(를) 부릅니다. 한 번에 하나씩 싸우세요.",
		["Jungle stalkers"] = "줄무늬정글랩터",
		["Mistvale gorillas"] = "안개계곡고릴라",
		["North-east of Mistvale, Zanzil's followers camp in the jungle; every one of them can carry the mixture."] = "안개계곡 골짜기 북동쪽 정글에 잔질의 추종자들이 야영하고 있습니다. 누구나 혼합물을 지니고 있을 수 있습니다.",
		["Pirate ghosts"] = "해적 유령",
		["Sawtooth crocolisks"] = "톱니악어",
		["Skullsplitter warriors"] = "백골가루부족 전사",
		["The Bloodsail ships"] = "붉은해적단 배",
		["The gorillas roam the valley around Unbagwa. The elders drop the giblets; any of them can drop a fang."] = "고릴라는 운바그와 주변 골짜기를 돌아다닙니다. 덩치큰 고릴라가 내장을 떨어뜨리고, 모든 고릴라가 송곳니를 떨어뜨릴 수 있습니다.",
		["The stalker raptors hunt the jungle south of {object:3202}, out towards the west coast."] = "랩터는 {object:3202} 남쪽 정글에서 서쪽 해안 쪽으로 사냥합니다.",
		["Venture Co. mine"] = "투자개발회사 광산",
		["West of the expedition, the Bloodscalp chiefs {npc:1061} and {npc:1062} stand together in the ruins of Zul'Kunda. Clear their guards first, then pull them."] = "원정대 서쪽, 줄쿤다의 폐허에 붉은머리부족 족장 {npc:1061}와(과) {npc:1062}이(가) 함께 서 있습니다. 먼저 호위병을 처치한 뒤 끌어오세요.",
		["Zanzil's camps"] = "잔질의 야영지",
		["Zul'Kunda"] = "줄쿤다",
		["Zul'Mamwe"] = "줄맘웨",
		["the {object:2076}"] = "{object:2076}",
} end)()
t.guides["forever/horde/40-50/02-feralas"] = (function() return {
		["Fly to {object:3202}"] = "{object:3202}(으)로 날아가기",
		["Grimtotem camp"] = "그림토템부족 야영지",
		["Keep riding west to the coast. The Coast Crawl Deepseers and Snapclaws on the beaches drop OOX-22/FE's distress beacon about one kill in forty: if one drops, use it to start the quest."] = "계속 서쪽 해안으로 가세요. 해변의 점쟁이 바다마크루라와 집게발 바다마크루라는 마흔 마리에 한 번꼴로 OOX-22/FE 조난 탐지기를 떨어뜨립니다. 얻으면 사용해 퀘스트를 시작하세요.",
		["North of the gnolls the ogres hold a hilltop outpost; pull the ogre-magi to you. The cobalt is in the dirt mounds around the outpost, and the scroll lies on the ground inside it."] = "놀 북쪽에서 오우거들이 언덕 위 전초기지를 차지하고 있습니다. 오우거 마법사는 끌어와서 처치하세요. 코발트는 전초기지 주변 흙더미에 있고, 두루마리는 그 안의 땅에 있습니다.",
		["Ride north-east to the goblin harbour on the coast."] = "북동쪽 해안의 고블린 항구로 가세요.",
		["Riding at 40"] = "40레벨 탈것 타기",
		["The Grimtotem tauren camp beside the sprite darters' grove; raiders, naturalists and shamans all carry horns."] = "그림토템부족 타우렌은 화살요정용의 숲 옆에 야영하고 있습니다. 침략자, 식물학자, 주술사 모두 뿔을 지니고 있습니다.",
		["The Zukk'ash hive burrows into the hills south-east of the camp; {quest:7731} waits in its deepest chamber."] = "주크애쉬 벌집은 야영지 남동쪽 언덕 속으로 파고들어 있습니다. {quest:7731}은(는) 가장 깊은 방에서 기다립니다.",
		["The battle map lies in the Woodpaw camp south of Mojache."] = "전투 지도는 모자케 야영지 남쪽의 덩굴발일족 야영지에 있습니다.",
		["Wolves: {npc:3362}, beside {npc:4752}."] = "늑대: {npc:4752} 옆의 {npc:3362}",
		["Woodpaw battle map"] = "덩굴발일족 전투 지도",
		["Woodpaw north camp"] = "덩굴발일족 북쪽 야영지",
		["Zeppelin to {zone:1454}"] = "{zone:1454}행 비행선",
		["for the {zone:1425}, around level 48"] = "48레벨쯤 {zone:1425}에서",
		["for {zone:1454}, around level 45"] = "45레벨쯤 {zone:1454}에서",
		["water pouches in your bags"] = "가방 속 물주머니",
		["{npc:3690}, riding trainer"] = "탈것 타기 상급자 {npc:3690}",
		["{npc:4752}, riding trainer"] = "탈것 타기 상급자 {npc:4752}",
		["{npc:4773}, riding trainer"] = "탈것 타기 상급자 {npc:4773}",
		["{npc:8115}: for {zone:1454}, around level 45"] = "{npc:8115}: 45레벨쯤 {zone:1454}에서",
		["{quest:2863}: one hour from now"] = "{quest:2863}: 지금부터 한 시간",
} end)()
t.guides["forever/horde/40-50/03-feralas"] = (function() return {
		["Dragon caves"] = "용 동굴",
		["Forest walkers"] = "나무정령",
		["Frayfeather hippogryphs"] = "공작날개 히포그리프",
		["North-west along the road, the Rage Scar yetis live around the caves in the hills. Any of them can also drop a {quest:7738}, which starts a quest of its own."] = "길을 따라 북서쪽으로 가면 언덕의 동굴 주변에 분노한 무쇠설인이 삽니다. 누구나 {quest:7738}도 떨어뜨릴 수 있으며, 이것은 별도의 퀘스트를 시작합니다.",
		["Onyxia's eggs"] = "오닉시아의 알",
		["Rage Scar yetis"] = "분노한 무쇠설인",
		["Ride back north to Brackenwall."] = "북쪽의 담쟁이 마을로 돌아가세요.",
		["Ride west along the road; the scroll lies at the water's edge in the swamp's far west."] = "길을 따라 서쪽으로 가세요. 두루마리는 늪 맨 서쪽의 물가에 있습니다.",
		["Sea elementals and sea sprays wash along the shore around the dock. Zap the giants with {item:18904} first: shrunken, they lose their elite strength. Shore striders wade in the water; the land walkers and cliff giants roam the hills further north."] = "부두 주변 해안에는 바다 정령과 바다 물보라 정령이 밀려다닙니다. 거인에게는 먼저 {item:18904}을(를) 쏘세요. 작아지면 정예의 힘을 잃습니다. 성큼걸이 해안거인은 물속을 걷고, 평지거인과 절벽거인은 더 북쪽 언덕을 돌아다닙니다.",
		["South of the vale the Frayfeather hippogryphs roost on the slopes; nearly every one drops sinew and metallic fragments."] = "골짜기 남쪽 비탈에 공작날개 히포그리프가 둥지를 틀고 있습니다. 거의 모두 힘줄과 금속 파편을 떨어뜨립니다.",
		["Sprite darters and forest walkers"] = "화살요정용과 나무정령",
		["The sprite darters flit over the grove just west of the camp and carry the {item:9589}; the Wandering Forest Walkers, a little further west, carry the Splintered Logs."] = "화살요정용은 야영지 바로 서쪽 숲 위를 날아다니며 {item:9589}을(를) 지니고 있습니다. 조금 더 서쪽의 떠도는 나무정령은 쪼개진 통나무를 지니고 있습니다.",
		["for the {npc:5598} in the {zone:1425}, around level 48"] = "48레벨쯤 {zone:1425}의 {npc:5598}에게",
		["for the {zone:1425} owlbeasts, around level 48"] = "48레벨쯤 {zone:1425}의 올빼미야수를 위해",
		["the {object:2555}"] = "{object:2555}",
		["{quest:7738}, a rare drop"] = "드물게 떨어지는 {quest:7738}",
} end)()
t.guides["forever/horde/40-50/04-tanaris"] = (function() return {
		["His next request needs the {item:10552} from elite cultists: leave it."] = "그의 다음 요청에는 정예 이교도가 지닌 {item:10552}이(가) 필요합니다. 받지 마세요.",
		["OOX-17/TN"] = "OOX-17/TN",
		["Only with the {item:11818}: back east to the {object:173265} at the dig site."] = "{item:11818}이(가) 있을 때만: 동쪽 발굴지의 {object:173265}(으)로 돌아가세요.",
		["Scrimshank's gear"] = "스크림섕크의 장비",
		["The {object:179827} board"] = "{object:179827} 게시판",
		["West of Gadgetzan, use the {item:8584} beside the water hole in the troll camp."] = "가젯잔 서쪽, 트롤 야영지의 물웅덩이 옆에서 {item:8584}을(를) 사용하세요.",
		["the {item:8526} grows in the {zone:1425}, around level 48"] = "{item:8526}은(는) 48레벨쯤 {zone:1425}에서 자랍니다",
		["the {object:173265}"] = "{object:173265}",
		["{item:11818}, a rare drop"] = "드물게 떨어지는 {item:11818}",
		["{item:8623}, a rare drop"] = "드물게 떨어지는 {item:8623}",
		["{npc:5955}'s escort"] = "{npc:5955} 호위",
		["{npc:7876}, beside the wind rider master"] = "윈드라이더 조련사 옆의 {npc:7876}",
} end)()
t.guides["forever/horde/40-50/05-the-hinterlands"] = (function() return {
		["East of the village, the violet flower grows in the hills."] = "마을 동쪽 언덕에 보라색 꽃이 자랍니다.",
		["Highvale"] = "깊은골짜기",
		["North along the coast, {npc:14731}'s picnic basket is on the small island; a {npc:14748} guards it."] = "해안을 따라 북쪽으로 가면 작은 섬에 {npc:14731}의 소풍 바구니가 있습니다. {npc:14748}이(가) 지키고 있습니다.",
		["OOX-09/HL"] = "OOX-09/HL",
		["Ride back north to the bloodmages."] = "북쪽의 피의 마법사에게 돌아가세요.",
		["South of the lodge the Witherbark trolls hold their villages. Every one of them carries a skull: with twenty, use {item:15002} to make the Laden Pike, then plant it inside the village."] = "산장 남쪽에서 마른나무껍질부족 트롤이 마을을 차지하고 있습니다. 모두 해골을 지니고 있습니다. 스무 개를 모아 {item:15002}을(를) 사용해 님보야의 무거운 창을 만든 뒤 마을 안에 꽂으세요.",
		["The big turtles crawl along the beaches north of the village. {npc:2491}'s port bottles lie on these beaches too, but his quest is not on this route. A snapjaw can drop OOX-09/HL's distress beacon, rarely: keep it."] = "큰 거북은 마을 북쪽 해변을 기어다닙니다. {npc:2491}의 포트와인 병도 이 해변에 있지만, 그의 퀘스트는 이 경로에 없습니다. 무쇠턱바다거북이 드물게 OOX-09/HL 조난 탐지기를 떨어뜨릴 수 있습니다. 보관하세요.",
		["The bloodmages"] = "피의 마법사",
		["Their follow-ups ask for the same parts again for a buff item and pay no experience: leave them."] = "후속 퀘스트는 강화 아이템을 위해 같은 재료를 다시 요구하며 경험치를 주지 않습니다. 받지 마세요.",
		["for {npc:6986} in {zone:1454}, around level 50"] = "50레벨쯤 {zone:1454}의 {npc:6986}에게",
		["for {npc:7825} in the {zone:1458}, around level 50"] = "50레벨쯤 {zone:1458}의 {npc:7825}에게",
		["{item:8704}, a rare drop"] = "드물게 떨어지는 {item:8704}",
		["{npc:14731}'s lunch"] = "{npc:14731}의 점심",
		["{npc:7801}'s camp"] = "{npc:7801}의 야영지",
} end)()
t.guides["forever/horde/40-50/06-azshara"] = (function() return {
		["Back north-east to {npc:8420}."] = "북동쪽 {npc:8420}에게 돌아가세요.",
		["Back to {object:3202}"] = "{object:3202}(으)로 돌아가기",
		["Follow the road south; the basilisks bask on the rocks east of it in the middle of the jungle. Their shards drop often."] = "길을 따라 남쪽으로 가세요. 바실리스크는 정글 한가운데, 길 동쪽 바위 위에서 햇볕을 쬡니다. 조각은 자주 나옵니다.",
		["Frayfeather Hippogryphs"] = "공작날개 히포그리프",
		["Ironjaw Basilisks"] = "무쇠턱 바실리스크",
		["Keep the deliveries for {npc:4046}, {npc:8659} and {npc:6522}: you pass {zone:1456}, {zone:1454} and the {zone:1458} later."] = "{npc:4046}, {npc:8659}, {npc:6522}에게 줄 배달품은 보관하세요. 나중에 {zone:1456}, {zone:1454}, {zone:1458}을(를) 지나갑니다.",
		["Keep {quest:3444}: {npc:7771}'s chest is opened on a later visit."] = "{quest:3444}은(는) 보관하세요. {npc:7771}의 상자는 나중에 다시 와서 엽니다.",
		["Only once all three robots are home"] = "로봇 세 대가 모두 돌아온 뒤에만",
		["Ride south-west to the ruins. The four tablets lie among the ruins, guarded by Spitelash naga; any Siren or Myrmidon can carry {npc:8420}'s rune."] = "남서쪽 폐허로 가세요. 석판 네 개가 폐허 곳곳에 있고 원한의꼬리일족 나가가 지킵니다. 원한의꼬리일족 세이렌이나 원한의꼬리일족 미르미돈 누구나 {npc:8420}의 룬을 지니고 있을 수 있습니다.",
		["Sprite Darters"] = "화살요정용",
		["Take the zeppelin back to {zone:1454}."] = "비행선을 타고 {zone:1454}(으)로 돌아가세요.",
		["The Highborne ghosts haunt the ruins just north of the shrine; the Haldarr satyrs camp a little further north."] = "명가 유령은 제단 바로 북쪽의 폐허를 떠돌고, 할다르 사티로스는 조금 더 북쪽에 진을 치고 있습니다.",
		["The blood elves' camp lies just south of {npc:8420}. His four pieces of equipment lie in the crates around the camp."] = "블러드 엘프 야영지는 {npc:8420} 바로 남쪽에 있습니다. 그의 장비 네 개는 야영지 주변 상자에 있습니다.",
		["The faerie dragons flit around the woods just west of the camp. Use the vessel on each one you kill."] = "요정용은 야영지 바로 서쪽 숲을 날아다닙니다. 처치할 때마다 단지를 사용하세요.",
		["The hippogryphs nest on the hills south-west of the camp. Kill one, then use the Muisek Vessel on its body."] = "히포그리프는 야영지 남서쪽 언덕에 둥지를 틉니다. 하나를 처치한 뒤 시체에 뮤세크 단지를 사용하세요.",
		["The treants wander the forest roads between the camp and the middle of {zone:1444}; there are only a few, so look along the paths."] = "나무정령은 야영지와 {zone:1444} 중앙 사이의 숲길을 떠돕니다. 수가 적으니 길을 따라 찾아보세요.",
		["The {object:2076} beside {npc:2519}"] = "{npc:2519} 옆의 {object:2076}",
		["To {object:3202}"] = "{object:3202}(으)로",
		["Undamaged Hippogryph Feathers"] = "온전한 히포그리프 깃털",
		["Wandering Forest Walkers"] = "떠도는 나무정령",
		["Zeppelin to {zone:1454}"] = "비행선 타고 {zone:1454}(으)로",
		["{npc:6986}, the Drag"] = "골목길의 {npc:6986}",
		["{npc:7876}'s tar and Pestlezugg's samples come from {zone:1449}."] = "{npc:7876}의 타르와 페슬저그의 표본은 {zone:1449}에서 구합니다.",
		["{npc:7876}, beside the wind rider master"] = "와이번 조련사 옆의 {npc:7876}",
		["{npc:8395}, at the east edge of the camp: no experience, only a teleport to Azshara Tower"] = "야영지 동쪽 끝의 {npc:8395}: 경험치 없음, 아즈샤라 탑으로 순간이동만 가능",
		["{npc:8659}, the {object:172960}"] = "{object:172960}의 {npc:8659}",
		["{quest:3761} is gathered in the next guide; {npc:4046}'s payment goes back to {npc:8587} later."] = "{quest:3761}은(는) 다음 가이드에서 모읍니다. {npc:4046}의 대금은 나중에 {npc:8587}에게 가져갑니다.",
} end)()
t.guides["forever/horde/50-60/01-un-goro-crater"] = (function() return {
		["Cross the south of the crater to the pylon on the western cliffs."] = "분화구 남쪽을 가로질러 서쪽 절벽의 수정탑으로 가세요.",
		["Eastern Pylon"] = "동쪽 수정탑",
		["Follow the cliffs south to {quest:3821}, the Firegut ogres' hill. {npc:9136}'s remains lie at its foot."] = "절벽을 따라 남쪽, 불자루 오우거의 언덕인 {quest:3821}(으)로 가세요. {npc:9136}의 유해는 언덕 기슭에 있습니다.",
		["Free Darrowshire Spirits: talk to them"] = "다로우샤이어 영혼 해방: 말 걸기",
		["From here on pick up every Power Crystal (blue, green, red, yellow) and every {quest:3761} pile you pass: 25 soil in all, 20 for Hamuul and 5 for Pestlezugg."] = "지금부터 지나가는 마력의 수정(파랑, 초록, 빨강, 노랑)과 {quest:3761} 더미를 모두 챙기세요. 흙은 모두 25개로, 하뮬에게 20개, 페슬저그에게 5개입니다.",
		["Into the {zone:1427}"] = "{zone:1427}(으)로",
		["Keep {npc:9118}'s {quest:4147} and {npc:8737}'s letter for later guides."] = "{npc:9118}의 {quest:4147}과(와) {npc:8737}의 편지는 이후 가이드를 위해 보관하세요.",
		["Lar'korwi Mates"] = "라르코르위의 짝",
		["North of Torwa, a dead Threshadon lies by the water."] = "토르와 북쪽 물가에 죽은 트레샤돈이 있습니다.",
		["Northern Pylon"] = "북쪽 수정탑",
		["Out of the refuge"] = "야영지 밖으로",
		["Pestlezugg's next quest needs the {npc:10041}, an elite boss. Skip it."] = "페슬저그의 다음 퀘스트는 정예 우두머리 {npc:10041}이(가) 필요합니다. 건너뛰세요.",
		["Ride down the east side of the crater to the pylon on the eastern cliffs."] = "분화구 동쪽을 따라 내려가 동쪽 절벽의 수정탑으로 가세요.",
		["Stegodons and ravasaurs"] = "스테고돈과 라바사우루스",
		["Take a {object:176092} from the crate next to Derrington for {quest:5096}, done on the way back. Equip the {quest:5401}: Scourgestones only drop while you wear it."] = "{quest:5096}을(를) 위해 델링턴 옆 상자에서 {object:176092}을(를) 챙기세요. 돌아오는 길에 완료합니다. {quest:5401}을(를) 착용하세요. 착용 중에만 스컬지석이 나옵니다.",
		["The Gorishi hive"] = "고리쉬 벌집",
		["The Lar'korwi Mates prowl the jungle north-west of {npc:9619}."] = "라르코르위의 짝은 {npc:9619} 북서쪽 정글을 배회합니다.",
		["The doll's head and its two sides lie in the houses around {npc:10926}; join them from your bags."] = "인형의 머리와 양쪽 몸통은 {npc:10926} 주변 집들에 있습니다. 가방에서 합치세요.",
		["The expedition's lost equipment lies in the south-west jungle."] = "원정대의 잃어버린 장비는 남서쪽 정글에 있습니다.",
		["The next guide starts here, at the chapel's flight master."] = "다음 가이드는 여기 예배당의 비행 조련사에서 시작합니다.",
		["The pylon stands on the slope east of the refuge."] = "수정탑은 야영지 동쪽 비탈에 있습니다.",
		["The raft lies on the shore of the south-eastern lake; the small pack sits in the water beside it."] = "뗏목은 남동쪽 호숫가에 있고, 작은 배낭은 그 옆 물속에 있습니다.",
		["Use the Mangled Journal to start it"] = "구겨진 일지를 사용해 시작하세요",
		["Western Pylon"] = "서쪽 수정탑",
		["{item:11116}, a rare drop"] = "{item:11116}, 희귀 획득물",
		["{npc:10879}, the {object:36078}, beside the bat master"] = "{object:36078}, 박쥐 조련사 옆의 {npc:10879}",
		["{npc:6522}, the {object:36073}"] = "{object:36073}의 {npc:6522}",
		["{npc:8390}, the Apothecarium: the vials fill in {zone:1447} later"] = "연금술 실험실의 {npc:8390}: 약병은 나중에 {zone:1447}에서 채웁니다",
		["{npc:9618}, just outside"] = "바로 밖의 {npc:9618}",
		["{npc:9619} camps in the south-east corner of the crater."] = "{npc:9619}은(는) 분화구 남동쪽 구석에 있습니다.",
		["{npc:9998}, at the entrance"] = "입구의 {npc:9998}",
		["{npc:9998}, at the refuge entrance"] = "야영지 입구의 {npc:9998}",
		["{quest:3822} walks the caves and mine tunnels of {quest:3821}; if he isn't home, clear the ogres around the entrances until he comes back."] = "{quest:3822}은(는) {quest:3821}의 동굴과 갱도를 돌아다닙니다. 없으면 돌아올 때까지 입구 주변 오우거를 처치하세요.",
} end)()
t.guides["forever/horde/50-60/02-felwood"] = (function() return {
		["Derrington's watchtowers, Vandis' cauldron and {npc:11615}'s barrel are done on a later visit: keep them."] = "데링턴의 감시탑, 반디스의 가마솥, {npc:11615}의 통은 나중에 들를 때 처리합니다. 보관하세요.",
		["Diseased Wolves"] = "역병에 걸린 늑대",
		["East of Bloodvenom Post, the cratered vale where the Entropic Beasts and Horrors roam. Kill two of each, then walk to each of the three fel-water craters."] = "피멍울 초소 동쪽, 혼돈의 불길과 혼돈의 소산물이 돌아다니는 구덩이투성이 골짜기입니다. 각각 두 마리씩 처치한 뒤, 지옥 물 구덩이 세 곳을 모두 걸어서 찾아가세요.",
		["Jadefire moonwell"] = "비취불꽃 달샘",
		["Keep the branch: {npc:5770} is in {zone:1456}."] = "가지를 보관하세요: {npc:5770}은(는) {zone:1456}에 있습니다.",
		["Keep {quest:5158}: {npc:5901} is in the {zone:1413}."] = "{quest:5158}을(를) 보관하세요: {npc:5901}은(는) {zone:1413}에 있습니다.",
		["Keep {quest:8465} for {zone:1452}."] = "{zone:1452}을(를) 위해 {quest:8465}을(를) 보관하세요.",
		["Northern crater"] = "북쪽 구덩이",
		["Only with 5 Deadwood Headdress Feathers"] = "마른가지일족 깃털 머리장식 5개가 있을 때만",
		["Ride north up the road again."] = "다시 길을 따라 북쪽으로 가세요.",
		["Ride north-west into Andorhal. {npc:10667} waits in the ruined inn on the west side of town; the skeletons inside are 54-57, so keep to the edges."] = "북서쪽의 안돌할로 가세요. {npc:10667}은(는) 마을 서쪽의 무너진 여관에서 기다립니다. 안쪽의 해골은 54-57레벨이니 가장자리로만 다니세요.",
		["Scarlet Crusade"] = "붉은십자군",
		["Southern crater"] = "남쪽 구덩이",
		["Take the kitten to the same moonwell and release it there; once it has turned into a {npc:10042}, bring it back to {npc:9996} and click on it to hand it over."] = "새끼 고양이를 같은 달샘에 데려가 풀어 주세요. {npc:10042}(으)로 변하면 {npc:9996}에게 데려가 클릭해서 건네세요.",
		["The Annals lie among the Musty Tomes in Andorhal's town hall; open them until you find the right one."] = "연대기는 안돌할 시청의 곰팡이 슨 고서 사이에 있습니다. 맞는 것을 찾을 때까지 열어 보세요.",
		["The Deadwood furbolg village just west of the tunnel. {npc:9462} (56) stands among them. {npc:11557}, a friendly furbolg, sits at the north end of the village."] = "터널 바로 서쪽의 마른가지일족 털보숭이 마을입니다. {npc:9462}(56)이(가) 그들 사이에 서 있습니다. 우호적인 털보숭이 {npc:11557}은(는) 마을 북쪽 끝에 앉아 있습니다.",
		["The Jadefire moonwell"] = "비취불꽃 달샘",
		["The diary lies in the farmhouse, the cabinet stands inside and the outhouse is behind it. A {npc:10816} carries the outhouse key; {npc:10836} comes out when you open the outhouse and carries the cabinet key."] = "일기는 농가 안에, 장식장은 그 안에, 변소는 그 뒤에 있습니다. {npc:10816}이(가) 변소 열쇠를 지니고 있습니다. 변소를 열면 {npc:10836}이(가) 나오며, 그가 장식장 열쇠를 지니고 있습니다.",
		["The druids' camp is just past the border."] = "드루이드 야영지는 경계를 막 지나서 있습니다.",
		["Western crater"] = "서쪽 구덩이",
		["{npc:10306}: the owlbeasts are in {zone:1452}"] = "{npc:10306}: 올빼미야수는 {zone:1452}에 있습니다",
		["{npc:10840}, at the graveyard's south end"] = "묘지 남쪽 끝의 {npc:10840}",
		["{npc:11554}, at the south edge of the camp"] = "야영지 남쪽 가장자리의 {npc:11554}",
		["{npc:1855}'s hunts are in the {zone:1423}: keep them for later."] = "{npc:1855}의 사냥은 {zone:1423}에서 합니다. 나중을 위해 보관하세요.",
		["{npc:9529}, just west of the camp"] = "야영지 바로 서쪽의 {npc:9529}",
		["{npc:9529}, on the west side of the Sanctuary"] = "성소 서쪽의 {npc:9529}",
		["{npc:9996}'s kitten"] = "{npc:9996}의 새끼 고양이",
		["{quest:8470}, a rare drop"] = "드물게 떨어지는 {quest:8470}",
} end)()
t.guides["forever/horde/50-60/03-winterspring"] = (function() return {
